{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket has no logging",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket storing CloudTrail logs has no logging enabled, making it difficult to track access and changes to the logs themselves."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket has versioning disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket storing CloudTrail logs has versioning disabled, which means that overwritten or deleted log files cannot be recovered."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket has no encryption",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket storing CloudTrail logs is not encrypted at rest, potentially exposing sensitive log data."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket = \"fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}\"\n}\n\nresource \"aws_s3_bucket_versioning\" \"cloudtrail_logs_versioning\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"cloudtrail_logs_encryption\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm = \"AES256\"\n    }\n  }\n}\n\nresource \"aws_s3_bucket_logging\" \"cloudtrail_logs_logging\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n  target_bucket = aws_s3_bucket.cloudtrail_logs.id\n  target_prefix = \"logs/\"\n}",
  "fix_summary": "Enabled versioning, server-side encryption, and logging for the S3 bucket storing CloudTrail logs to improve security and recoverability."
}
